<?php require '../config/config.php';role(['administrator','pustakawan']);$mo=$_GET['month']??date('Y-m');header('Content-Type:application/vnd.ms-excel; charset=utf-8');header('Content-Disposition:attachment; filename=laporan_'.$mo.'.xls');echo '<table border=1><tr><th>Anggota</th><th>Kode</th><th>Judul</th><th>Pinjam</th><th>Jatuh Tempo</th><th>Kembali</th><th>Denda</th></tr>';$s=$pdo->prepare("SELECT u.name,c.code,b.title,l.loan_date,l.due_date,l.returned_at,l.fine FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE DATE_FORMAT(l.loan_date,'%Y-%m')=? OR DATE_FORMAT(l.returned_at,'%Y-%m')=?");$s->execute([$mo,$mo]);foreach($s as $r){echo '<tr>';foreach($r as $v)echo '<td>'.htmlspecialchars((string)$v).'</td>';echo '</tr>';}echo '</table>';
